import type { Database } from "@/types/database.types";
import { createServerClient as createSSRServerClient } from "@supabase/ssr";
import {
  createClient as createSupabaseClient,
  SupabaseClient,
} from "@supabase/supabase-js";
import { cookies } from "next/headers";
import { NextResponse, type NextRequest } from "next/server";

// Cookie domain helper - must match auth-guard.ts for consistency
function getCookieDomain(request: NextRequest): string | undefined {
  const host = request.headers.get("host") || "";
  const isWWW = host.startsWith("www.");
  const rootDomain = isWWW ? host.replace("www.", "") : host;
  return rootDomain.includes(":") ? undefined : `.${rootDomain}`;
}

type SupabaseCookie = {
  name: string;
  value: string;
  options?: Parameters<NextResponse["cookies"]["set"]>[2];
};

type ImpersonationCookieOverride = {
  name: string;
  value: string;
};

/**
 * Creates a Supabase service-role client (elevated privileges, bypasses RLS).
 * Use in API routes and Server Actions that need full DB access.
 */
export function createClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL?.trim();
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY?.trim();

  if (!url || !key) {
    throw new Error("Missing Supabase environment variables");
  }

  return createSupabaseClient<Database>(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

/**
 * Creates a Supabase SSR client.
 *
 * Usage:
 * - Route Handler (sync): createServerClient(request, response)
 * - Server Component (async): await createServerClient()
 */

export function createServerClient(
  request: NextRequest,
  response: NextResponse,
  impersonationCookies?: ImpersonationCookieOverride[],
): SupabaseClient<Database>;
// eslint-disable-next-line no-redeclare
export function createServerClient(): Promise<SupabaseClient<Database>>;
// eslint-disable-next-line no-redeclare
export function createServerClient(
  request?: NextRequest,
  response?: NextResponse,
  impersonationCookies?: ImpersonationCookieOverride[],
): SupabaseClient<Database> | Promise<SupabaseClient<Database>> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!.trim();
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!.trim();

  // Route Handler path — synchronous, needs request + response for cookie handling
  if (request && response) {
    const cookieDomain = getCookieDomain(request);
    const host = request.headers.get("host") || "";
    const isLocalhost = host.startsWith("localhost") || host.startsWith("127.0.0.1");
    const useSecure = !isLocalhost;
    return createSSRServerClient<Database>(url, key, {
      cookieEncoding: "raw",
      cookies: {
        getAll: () => {
          const all = request.cookies.getAll();
          if (!impersonationCookies || impersonationCookies.length === 0) {
            return all;
          }
          // During impersonation the request still carries the admin's auth
          // cookies; swap them for the target user's tokens so that Supabase
          // SSR sees the impersonated session.
          const impersonationNames: Record<string, true> = {};
          for (const c of impersonationCookies) {
            impersonationNames[c.name] = true;
          }
          const filtered = all.filter(
            (c) =>
              !impersonationNames[c.name] &&
              !c.name.startsWith("sb-") &&
              c.name !== "__impersonation_banner" &&
              c.name !== "__impersonate",
          );
          return [...filtered, ...impersonationCookies];
        },
        setAll: (cookiesToSet: SupabaseCookie[]) => {
          cookiesToSet.forEach((cookie) => {
            const { name, value, options } = cookie;
            response.cookies.set(name, value, {
              ...options,
              path: "/",
              domain: cookieDomain,
              sameSite: "lax",
              secure: useSecure,
            });
          });
        },
      },
      global: {
        fetch: globalThis.fetch,
      },
    });
  }

  // Server Component / Server Action path — async, reads from next/headers
  // We return the Promise directly to be awaited
  return (async () => {
    const cookieStore = await cookies();
    return createSSRServerClient<Database>(url, key, {
      cookieEncoding: "raw",
      auth: {
        autoRefreshToken: false, // RSC cannot write cookies back — never refresh here
      },
      cookies: {
        getAll: () => cookieStore.getAll(),
        setAll: (cookiesToSet: SupabaseCookie[]) => {
          try {
            cookiesToSet.forEach((cookie) => {
              const { name, value, options } = cookie;
              cookieStore.set(name, value, options);
            });
          } catch (err) {
            // Next.js 15+: cookieStore.set er ikke tillatt i RSC — sesjonsoppdatering skjer i middleware/route.
            // getUser() kan fortsatt trigge Supabase refresh-kall som forsøker setAll; ignorer her.
            console.warn("[RSC] Failed to persist refreshed auth cookies:", err);
          }
        },
      },
      global: {
        fetch: globalThis.fetch,
      },
    });
  })();
}
